messages.content:
Parse data from {{38.message.text}} into JSON, extracting symptoms and a self-reported pain scale (1-10). Map severity as follows: 1-3=Low, 4-6=Medium, 7-8=High, 9-10=Critical. Parse {{38.message.from.id}} as PatientID. Output only the JSON object and no additional text:
{
 "Symptoms": ["symptom1", "symptom2", ...],
 "Severity": "Low|Medium|High|Critical",
 "PatientID": "string"
}

mapper.array:
{
  "array": "{{slice(52.array.id; 0; if(((35.Severity = \) + "High\" + or + (35.Severity = \) + "Critical\"; min(3; length(52.array)); if((35.Severity = \) + "Medium\"; min(6; length(52.array)); min(9; length(52.array))))))}}"
}

mapper.text:
Diagnosis: {{35.Diagnosis}}
Severity: {{35.Severity}}
Available Appointments: {{map(slice(52.array; if((35.Severity = "High") + or + "Critical"; 0; if(35.Severity = "Medium"; 3; 6)); 3); "Option " + (index + 1) + ": " + formatDate(AppointmentTime; "YYYY-MM-DD HH:mm") + "
")}}
